import { MeshBasicNodeMaterial, PlaneGeometry, Group } from 'three/webgpu';
import { float } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new Group();
  const resources = [];

  // --- Plane with texture ---
  const textureUrl = config.imageUrl || (config.assets && config.assets.length > 0 && config.assets[0].url) || '/prism-mock/home/nodes/cta-hero-isolated.png';
  const texture = ctx.textureLoader.load(textureUrl);

  // Atlas region: (0,0,W,H) → full texture (assume image is 512x320)
  texture.offset.set(0, 0);
  texture.repeat.set(1, 1);

  // Plane dimensions derived from texture aspect ratio (512/320 = 1.6)
  const planeWidth = 1.6;
  const planeHeight = 1.0;
  const planeGeo = new PlaneGeometry(planeWidth, planeHeight);
  resources.push(planeGeo);

  const material = new MeshBasicNodeMaterial({
    map: texture,
    transparent: true,
    side: 0 // DoubleSide? Not needed for plane
  });
  resources.push(material);

  const plane = new Group(); // use group to hold mesh or just mesh directly
  const mesh = new Group();
  mesh.geometry = planeGeo;
  mesh.material = material;
  plane.add(mesh);
  group.add(plane);

  // --- Text overlay using ctx.fontAtlas ---
  const textContent = config.textContent && config.textContent.length > 0
    ? config.textContent[0]
    : { text: 'Atelier Noir — precise · luxury · technical', fontSize: 0.2, fontWeight: 400 };

  const textOptions = {
    text: textContent.text || 'Atelier Noir — precise · luxury · technical',
    fontFamily: 'Lora',
    fontWeight: textContent.fontWeight || 400,
    fontSize: textContent.fontSize || 0.2, // subhead scale token
    align: 'center',
    anchor: { x: 0.5, y: 0.5 }
  };

  if (ctx.fontAtlas && typeof ctx.fontAtlas.create === 'function') {
    const textMesh = ctx.fontAtlas.create(textOptions);
    if (textMesh) {
      textMesh.position.z = 0.01; // slightly in front of plane
      group.add(textMesh);
      // textMesh resources (geometry, material) are managed by fontAtlas, but we can mark for cleanup if needed
      // Since we don't have explicit disposal, we assume ctx.fontAtlas handles it or we add to resources if possible
      // To be safe, we keep reference if textMesh has dispose
      if (textMesh.material && textMesh.material.dispose) resources.push(textMesh.material);
      if (textMesh.geometry && textMesh.geometry.dispose) resources.push(textMesh.geometry);
    }
  }

  // --- Apply scene placement ---
  if (config.scenePosition) {
    group.position.set(
      config.scenePosition.x !== undefined ? config.scenePosition.x : 0,
      config.scenePosition.y !== undefined ? config.scenePosition.y : 1.85,
      config.scenePosition.z !== undefined ? config.scenePosition.z : 0
    );
  }
  if (config.sceneRotation) {
    group.rotation.set(
      config.sceneRotation.x || 0,
      config.sceneRotation.y || 0,
      config.sceneRotation.z || 0
    );
  }
  if (config.sceneScale) {
    group.scale.set(
      config.sceneScale.x || 1,
      config.sceneScale.y || 1,
      config.sceneScale.z || 1
    );
  }

  // --- Event handlers (none) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    resources.forEach(r => {
      if (r && typeof r.dispose === 'function') r.dispose();
    });
    // Also kill any GSAP timelines (none in this node)
  };

  return group;
}
